import XCTest
@testable import JavaIntelligence
import LanguageSyntax

/// `ParseEdit.diff` and `point(forByteOffset:in:)` were rewritten to scan with blocked `memcmp` and to
/// find one start point instead of three. The originals stay as `referenceDiff` and `referencePoint`;
/// everything here compares the new code with them on generated bytes, then checks that the edits
/// still drive tree-sitter to the same trees.
final class ParseEditDiffTests: XCTestCase {
    private struct Generator: RandomNumberGenerator {
        var state: UInt64
        mutating func next() -> UInt64 {
            state = state &* 6364136223846793005 &+ 1442695040888963407
            return state
        }
    }

    private static let pieces: [[UInt8]] = [
        Array("a".utf8), Array("abc def".utf8), [10], [13, 10], [13], Array("\n\n".utf8), Array("é".utf8), Array("日本語".utf8),
        Array("😀".utf8), Array("    ".utf8), Array("{ }".utf8), Array("// c\n".utf8), Array("x = 1;\n".utf8)
    ]

    private func generated(_ generator: inout Generator, pieceCount: Int) -> [UInt8] {
        (0..<pieceCount).flatMap { _ in Self.pieces.randomElement(using: &generator)! }
    }

    /// Cut points that do not split a UTF-8 sequence, plus both ends.
    private func boundaries(_ bytes: [UInt8]) -> [Int] {
        (0...bytes.count).filter { $0 == bytes.count || (bytes[$0] & 0xC0) != 0x80 }
    }

    private func assertSameEdit(_ old: [UInt8], _ new: [UInt8], _ message: @autoclosure () -> String, file: StaticString = #filePath, line: UInt = #line) {
        let fast = ParseEdit.diff(from: old, to: new)
        let reference = ParseEdit.referenceDiff(from: old, to: new)
        switch (fast, reference) {
        case (nil, nil):
            break
        case let (fast?, reference?):
            XCTAssertTrue(fast.isEqual(to: reference), "\(message()): fast \(fast.startByte)..\(fast.oldEndByte)->\(fast.newEndByte) \(fast.points) vs reference \(reference.startByte)..\(reference.oldEndByte)->\(reference.newEndByte) \(reference.points)", file: file, line: line)
        default:
            XCTFail("\(message()): one of them found an edit and the other did not", file: file, line: line)
        }
    }

    func testDiffMatchesTheReferenceOnGeneratedEdits() {
        var generator = Generator(state: 0xD1FF)
        for round in 0..<4_000 {
            let old = generated(&generator, pieceCount: Int.random(in: 0...60, using: &generator))
            var new = old
            let places = boundaries(new)
            // 0 to 3 edits: none gives equal arrays; several give one merged difference.
            for _ in 0..<Int.random(in: 0...3, using: &generator) {
                let currentPlaces = boundaries(new)
                let start = currentPlaces.randomElement(using: &generator)!
                let end = currentPlaces.filter { $0 >= start }.randomElement(using: &generator)!
                new.replaceSubrange(start..<end, with: Bool.random(using: &generator) ? generated(&generator, pieceCount: Int.random(in: 0...4, using: &generator)) : [])
            }
            _ = places
            assertSameEdit(old, new, "round \(round)")
        }
    }

    func testDiffMatchesTheReferenceAroundBlockBoundaries() {
        // The new scan compares 4,096-byte blocks: edits just before, on and after a boundary, near
        // both ends, and in documents shorter than, equal to and longer than a block.
        var generator = Generator(state: 0xB10C)
        for count in [0, 1, 4095, 4096, 4097, 8191, 8192, 8193, 12_289, 40_000] {
            let old = (0..<count).map { _ in UInt8(ascii: "a") + UInt8.random(in: 0..<3, using: &generator) } .map { $0 == UInt8(ascii: "c") ? UInt8(10) : $0 }
            var offsets = Set([0, 1, count / 2, max(0, count - 1), count])
            for boundary in [4096, 8192, 12_288] { offsets.formUnion([boundary - 1, boundary, boundary + 1, count - boundary, count - boundary - 1, count - boundary + 1]) }
            for offset in offsets.filter({ $0 >= 0 && $0 <= count }) {
                var inserted = old
                inserted.insert(UInt8(ascii: "Z"), at: offset)
                assertSameEdit(old, inserted, "count \(count) insert at \(offset)")
                assertSameEdit(inserted, old, "count \(count) delete at \(offset)")
                if offset < count {
                    var replaced = old
                    replaced[offset] = UInt8(ascii: "Z")
                    assertSameEdit(old, replaced, "count \(count) replace at \(offset)")
                    var multiline = old
                    multiline.replaceSubrange(offset..<min(count, offset + 3), with: [10, 10, UInt8(ascii: "Z")])
                    assertSameEdit(old, multiline, "count \(count) multiline at \(offset)")
                }
            }
            assertSameEdit(old, old, "count \(count) identical")
        }
    }

    func testPointsMatchTheReference() {
        var generator = Generator(state: 0x9017)
        for round in 0..<2_000 {
            let bytes = generated(&generator, pieceCount: Int.random(in: 0...80, using: &generator))
            for offset in Set([0, bytes.count, bytes.count + 3, bytes.count / 2] + (0..<5).map { _ in Int.random(in: 0...(bytes.count + 1), using: &generator) }) {
                XCTAssertEqual(
                    ParseEdit.position(forByteOffset: offset, in: bytes), ParseEdit.referencePosition(forByteOffset: offset, in: bytes),
                    "round \(round) offset \(offset)"
                )
            }
        }
    }

    /// The newline count reads eight bytes at a time. Bytes next to 0x0A (0x0B, 0x09, 0x8A, 0x00, 0xFF) are
    /// where a careless zero-byte test miscounts, so they make up most of the input, and every start
    /// and length is tried so each alignment and tail is covered.
    func testNewlineCountMatchesANaiveCount() {
        var generator = Generator(state: 0x5A12)
        let interesting: [UInt8] = [10, 10, 11, 9, 0x8A, 0x0B, 0, 255, 0x7F, 0x80, 0x01, 13, 97]
        for round in 0..<300 {
            let count = Int.random(in: 0...200, using: &generator)
            let bytes = (0..<count).map { _ in
                Int.random(in: 0..<4, using: &generator) == 0 ? UInt8.random(in: 0...255, using: &generator) : interesting.randomElement(using: &generator)!
            }
            bytes.withUnsafeBufferPointer { buffer in
                for from in stride(from: 0, through: count, by: Int.random(in: 1...3, using: &generator)) {
                    for to in from...count {
                        let expected = bytes[from..<to].filter { $0 == 10 }.count
                        XCTAssertEqual(ParseEdit.newlineCount(in: buffer, from: from, to: to), expected, "round \(round) \(from)..<\(to)")
                    }
                }
            }
        }
    }

    func testEmptyDocumentsAndDocumentBoundaries() {
        assertSameEdit([], [], "both empty")
        assertSameEdit([], Array("x".utf8), "typing into an empty document")
        assertSameEdit(Array("x".utf8), [], "deleting everything")
        assertSameEdit(Array("x\n".utf8), Array("\n".utf8), "first byte")
        assertSameEdit(Array("\n".utf8), Array("x\n".utf8), "before the first newline")
        assertSameEdit(Array("a\r\nb".utf8), Array("a\r\nbc".utf8), "after the last byte")
        assertSameEdit(Array("a\r\nb".utf8), Array("a\nb".utf8), "CRLF to LF")
        assertSameEdit(Array("😀".utf8), Array("😁".utf8), "last byte of a surrogate-pair scalar differs")
    }

    func testLargeDocuments() {
        var generator = Generator(state: 0x1A56)
        let old = generated(&generator, pieceCount: 120_000)
        XCTAssertGreaterThan(old.count, 300_000)
        let places = boundaries(old)
        for position in [0, 1, old.count / 4, old.count / 2, old.count * 3 / 4, old.count - 1, old.count] {
            let start = places.last { $0 <= position }!
            var inserted = old
            inserted.insert(contentsOf: Array("typed\n  ".utf8), at: start)
            assertSameEdit(old, inserted, "multiline insert at \(start)")
            var single = old
            single.insert(UInt8(ascii: "q"), at: start)
            assertSameEdit(old, single, "typed byte at \(start)")
            var deleted = old
            deleted.removeSubrange(start..<min(old.count, start + 200).advanced(by: 0))
            if let end = boundaries(deleted).first(where: { $0 >= start }) { _ = end }
            assertSameEdit(old, deleted, "deleted 200 bytes at \(start)")
        }
    }

    // MARK: - Trees

    /// An edit that is subtly wrong still produces a valid-looking tree-sitter edit, so the check
    /// that matters is the tree: parse incrementally with the new edit and with the reference edit,
    /// and compare both with a parse from scratch whenever the text parses cleanly.
    func testIncrementalTreesAreTheSameWithEitherEdit() throws {
        var generator = Generator(state: 0x7EE5)
        let parser = JavaSyntaxParser()
        let base = (0..<40).map { index in
            "    public int method\(index)(int a) {\r\n        int é\(index) = a * 2;\n        return é\(index) + \(index);\n    }\n"
        }
        let source = "package demo;\nimport java.util.*;\npublic class Big {\n" + base.joined() + "}\n"
        let fragments = ["x", " ", "\n", "\r\n", ";", "int v = 1;", "日本", "😀", "foo(", ")", "{", "}", "/* c */", "// c\n"]
        var cleanComparisons = 0
        for round in 0..<60 {
            var bytes = Array(source.utf8)
            var tree = try XCTUnwrap(parser.parse(source))
            for step in 0..<12 {
                var next = bytes
                // Mostly whole-line edits, which keep Java valid (so incremental can be compared
                // with a fresh parse); the rest are arbitrary and usually break the syntax.
                let lineStarts = [0] + bytes.indices.filter { bytes[$0] == 10 }.map { $0 + 1 }.filter { $0 < bytes.count }
                switch Int.random(in: 0..<5, using: &generator) {
                case 0, 1:
                    let at = lineStarts.randomElement(using: &generator)!
                    next.insert(contentsOf: Array(["        int v\(step) = 1;\n", "        // 日本😀\r\n", "\n", "        v += 2; /* c */\n"].randomElement(using: &generator)!.utf8), at: at)
                case 2:
                    let at = lineStarts.randomElement(using: &generator)!
                    let lineEnd = (bytes[at...].firstIndex(of: 10).map { $0 + 1 }) ?? bytes.count
                    if !bytes[at..<lineEnd].contains(where: { $0 == UInt8(ascii: "{") || $0 == UInt8(ascii: "}") }) { next.removeSubrange(at..<lineEnd) }
                default:
                    let places = boundaries(bytes)
                    let start = places.randomElement(using: &generator)!
                    let end = places.filter { $0 >= start && $0 - start <= 30 }.randomElement(using: &generator)!
                    next.replaceSubrange(start..<end, with: Array((Bool.random(using: &generator) ? fragments.randomElement(using: &generator)! : "").utf8))
                }
                let text = String(decoding: next, as: UTF8.self)
                guard Array(text.utf8) == next, next != bytes else { continue }

                let fast = try XCTUnwrap(ParseEdit.diff(from: bytes, to: next))
                let reference = try XCTUnwrap(ParseEdit.referenceDiff(from: bytes, to: next))
                XCTAssertTrue(fast.isEqual(to: reference), "round \(round) step \(step)")

                func reparse(_ edit: ParseEdit) throws -> JavaSyntaxTree {
                    let edited = tree.copy()
                    edited.apply(edit)
                    return try XCTUnwrap(parser.parseIncremental(oldTree: edited, source: text))
                }
                let withFast = try reparse(fast)
                let withReference = try reparse(reference)
                XCTAssertEqual(withFast.rootNode.sExpression, withReference.rootNode.sExpression, "round \(round) step \(step)")
                if let fresh = parser.parse(text), !fresh.rootNode.hasError, !withFast.rootNode.hasError {
                    XCTAssertEqual(withFast.rootNode.sExpression, fresh.rootNode.sExpression, "round \(round) step \(step): incremental differs from a fresh parse")
                    cleanComparisons += 1
                }
                tree = withFast
                bytes = next
            }
        }
        XCTAssertGreaterThan(cleanComparisons, 50, "too few clean texts to say anything about incremental correctness")
    }
}
